    # The demo indicates row 1 and final row contain pattern segments between 9s;
    # connected vertical runs of 4 adjacent to such segments are also marked.
    h,w=len(grid),len(grid[0])
    out=[r[:] for r in grid]
    seeds=set()
    for i,row in enumerate(grid):
        j=0
        while j<w:
            if row[j]==4:
                k=j
                while k<w and row[k]==4:k+=1
                if k-j>=2 and j>0 and row[j-1]==9 and k<w and row[k]==9:
                    seeds.update((i,x) for x in range(j,k))
                j=k
            else:j+=1
    # extend vertical consecutive 4s from seed columns
    for i,j in list(seeds):
        out[i][j]=2
        for di in (-1,1):
            r=i+di
            while 0<=r<h and grid[r][j]==4:
                out[r][j]=2;r+=di
    return out
"
