    bg = counts.most_common(1)[0][0]
    marker = min(counts, key=counts.get)
    out = [row[:] for row in grid]

    def connect_line(vals, coords):
        # Runs of marker points; connect from leading edge to first run and
        # between runs, but not past the final run.
        runs = []
        i = 0
        while i < len(vals):
            if vals[i] == marker:
                a = i
                while i < len(vals) and vals[i] == marker:
                    i += 1
                runs.append((a, i - 1))
            else:
                i += 1
        if runs:
            intervals = [(0, runs[0][0] - 1)]
            intervals += [(runs[k][1] + 1, runs[k+1][0] - 1) for k in range(len(runs)-1)]
            for a, b in intervals:
                for i in range(a, b+1):
                    r, c = coords(i)
                    if grid[r][c] == bg:
                        out[r][c] = 2

    for r in range(h):
        connect_line(grid[r], lambda c, r=r: (r, c))
    for c in range(w):
        connect_line([grid[r][c] for r in range(h)], lambda r, c=c: (r, c))
    return out
