    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    marker = min(counts, key=counts.get)
    background = max(counts, key=counts.get)
    out = [row[:] for row in grid]

    def mark_gaps(values, coord):
        runs = []
        i = 0
        while i < len(values):
            if values[i] == marker:
                start = i
                while i < len(values) and values[i] == marker:
                    i += 1
                runs.append((start, i - 1))
            else:
                i += 1
        for (_, end), (start, _) in zip(runs, runs[1:]):
            for k in range(end + 1, start):
                r, c = coord(k)
                if grid[r][c] == background:
                    out[r][c] = 2

    for r in range(h):
        mark_gaps(grid[r], lambda c, r=r: (r, c))
    for c in range(w):
        mark_gaps([grid[r][c] for r in range(h)], lambda r, c=c: (r, c))
    return out
